// Hops on a beat: `count` hops, one every `every` ms, each `len` ms in the air.
function beats(every, offset, len, count) {
  var out = [];
  for (var k = 0; k < count; k++) out.push([k * every + offset, k * every + offset + len]);
  return out;
}
